// Points the engine at one course: writes src/course/_data.js and _active.js from courses/<slug>/.
//   node scripts/use-course.mjs [slug]      (default: $COURSE, or "chroma")
// The generated file embeds course.json and imports the course's lab code, animations and
// optional world.json, so that the same modules load in the browser build and in Node scripts.
import { readFileSync, writeFileSync, existsSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const here = path.dirname(fileURLToPath(import.meta.url));
const slug = process.argv[2] || process.env.COURSE || 'chroma';
// a course is courses/<slug>/; test fixtures (engine/tests/fixtures/<slug>/, never published) also work
const pub = path.join(here, '..', '..', 'courses', slug), fix = path.join(here, '..', 'tests', 'fixtures', slug);
const dir = existsSync(path.join(pub, 'course.json')) || !existsSync(path.join(fix, 'course.json')) ? pub : fix;
const rel = path.relative(path.join(here, '..', 'src', 'course'), dir).split(path.sep).join('/');
if (!existsSync(path.join(dir, 'course.json'))) { console.error(`No course at courses/${slug}/course.json`); process.exit(1); }
const data = JSON.parse(readFileSync(path.join(dir, 'course.json'), 'utf8'));
const world = existsSync(path.join(dir, 'world.json')) ? JSON.parse(readFileSync(path.join(dir, 'world.json'), 'utf8')) : {};
// WORLD_JSON='{"gen":false}' overrides world.json for one build (tests of the switches: scripts/playswitches.mjs)
if (process.env.WORLD_JSON) Object.assign(world, JSON.parse(process.env.WORLD_JSON));
const labs = existsSync(path.join(dir, 'labs')) ? readdirSync(path.join(dir, 'labs')).filter((f) => f.endsWith('.js')).map((f) => f.slice(0, -3)) : [];
const anims = existsSync(path.join(dir, 'anims.js'));
const head = `// GENERATED by scripts/use-course.mjs from courses/${slug}/. Do not edit: change the course and run it again.\n`;
// data only, no imports: safe to load from anywhere
writeFileSync(path.join(here, '..', 'src', 'course', '_data.js'), `${head}export const SLUG = ${JSON.stringify(slug)};
export const COURSE_DIR = ${JSON.stringify(path.relative(path.join(here, '..', '..'), dir).split(path.sep).join('/'))};
export const DATA = ${JSON.stringify(data)};
export const WORLD = ${JSON.stringify(world)};
`);
// the course's code: lab stations and animations
writeFileSync(path.join(here, '..', 'src', 'course', '_active.js'), `${head}${labs.map((l) => `import lab_${l} from '${rel}/labs/${l}.js';`).join('\n')}
${anims ? `import { ANIMS as A } from '${rel}/anims.js';` : 'const A = {};'}

export const MOUNTS = { ${labs.map((l) => `${JSON.stringify(l)}: lab_${l}`).join(', ')} };
export const ANIMS = A;
`);
console.log(`engine now uses courses/${slug} (${data.concepts.length} concepts, lab code for ${labs.length})`);
